-- Generated by scripts/gen_patent_query.py from config/domains.yaml — do not edit by hand.
-- Regenerate: .venv/bin/python scripts/gen_patent_query.py
--
-- US granted patents per technology domain per grant year, 2000–2025.
-- Source: patents-public-data.patents.publications (Google Patents Public
-- Data, CC BY 4.0). Run in the BigQuery sandbox (no billing account needed);
-- download the result as CSV to data/patents/patent_counts.csv.
--
-- Concordance: a configured subgroup '00' code matches every leaf in its
-- group; a specific subgroup matches exactly. A patent matching several
-- domains counts once per matched domain (multi-membership; the known
-- overlaps are parent/child pairs — see scripts/gen_patent_query.py).

WITH cfg (cpc_group, cpc_subgroup, domain) AS (
  VALUES
  ('G06N20', '00', 'artificial_intelligence'),
  ('G06N3', '00', 'artificial_intelligence'),
  ('G06F18', '00', 'artificial_intelligence'),
  ('G06N3', '08', 'generative_ai'),
  ('G06N3', '04', 'generative_ai'),
  ('G06N3', '092', 'ai_agents'),
  ('G05B13', '00', 'ai_agents'),
  ('G06N10', '00', 'quantum_computing'),
  ('G06N10', '20', 'quantum_computing'),
  ('G06N10', '40', 'quantum_computing'),
  ('G06N10', '70', 'quantum_error_correction'),
  ('H01M10', '0562', 'solid_state_batteries'),
  ('H01M2300', '0068', 'solid_state_batteries'),
  ('C25B1', '04', 'clean_hydrogen'),
  ('C25B15', '00', 'clean_hydrogen'),
  ('B01D53', '62', 'carbon_capture'),
  ('B01J20', '00', 'carbon_capture'),
  ('C12N15', '00', 'synthetic_biology'),
  ('A61B5', '16', 'brain_computer_interfaces'),
  ('G06F3', '01', 'brain_computer_interfaces'),
  ('H04L63', '00', 'cybersecurity'),
  ('G06F21', '00', 'cybersecurity'),
  ('H04L9', '32', 'blockchain'),
  ('G06Q20', '00', 'blockchain'),
  ('H04L67', '12', 'internet_of_things'),
  ('H04W4', '33', 'internet_of_things'),
  ('G06F9', '50', 'edge_computing'),
  ('H04L67', '10', 'edge_computing'),
  ('G05B17', '02', 'digital_twins'),
  ('G06F30', '00', 'digital_twins'),
  ('G05B19', '4185', 'smart_manufacturing'),
  ('B60W60', '00', 'autonomous_vehicles'),
  ('G01C21', '00', 'autonomous_vehicles'),
  ('B64G1', '00', 'space_technologies'),
  ('H01L21', '00', 'advanced_semiconductors'),
  ('H01L29', '00', 'advanced_semiconductors'),
  ('C12Q1', '00', 'biotechnology'),
  ('C12P1', '00', 'biotechnology')
),
us_grants AS (
  SELECT
    p.publication_number,
    DIV(p.grant_date, 10000) AS grant_year,
    c.code AS cpc_code
  FROM `patents-public-data.patents.publications` AS p,
       UNNEST(p.cpc) AS c
  WHERE p.country_code = 'US'
    AND p.grant_date BETWEEN 20000101 AND 20251231
    AND p.kind_code LIKE 'B%'
),
matched AS (
  SELECT
    g.publication_number,
    g.grant_year,
    cfg.domain
  FROM us_grants AS g
  JOIN cfg
    ON cfg.cpc_group = SPLIT(g.cpc_code, '/')[OFFSET(0)]
   AND (cfg.cpc_subgroup = '00'
        OR cfg.cpc_subgroup = SPLIT(g.cpc_code, '/')[SAFE_OFFSET(1)])
)
SELECT
  domain,
  grant_year AS year,
  COUNT(DISTINCT publication_number) AS patents
FROM matched
GROUP BY domain, grant_year
ORDER BY domain, grant_year;
